library_mount_modal_usb_warn_body: "/mnt/usb* と /mnt/ext* は PS5 カーネルの USB ホットプラグ名前空間に属しており、そこへのイメージのマウントはほとんどのファームウェアでカーネルポリシーによりブロックされます。「Operation not permitted」で失敗する場合は /mnt/ps5upload（ペイロード専用のマウントルート）または /data に切り替えてください — どちらもカーネルパッチなしで動作します。",
library_mount_modal_usb_warn_switch: "/mnt/ps5upload/ に切り替え",
