"backport_no_larger": "このゲームには、どのセットにも含まれないライブラリが必要です。より完全なパックをインポートするか、別の本体をスキャンしてください。",
"backport_verifying": "起動して様子を見ています。起動はとても不安定で 1 回の失敗では何も分からないため、失敗した起動は再試行します。",
