"backport_verify_unknown": "うまくいったか判断できませんでした",
"backport_verify_unknown_body": "起動結果が一致しなかったため、ライブラリについては何も言えません。起動はそれだけでよく失敗するので、結果が混ざっていても意味がありません。自分で起動してみて、遊べなければ元に戻してください。",
"backport_get_more": "ライブラリを追加で入手…",
"backport_needs_libraries": "{name} のバックポートには、置き換え用のシステムライブラリが必要です。Sony のファイルなので ps5upload には同梱できません。所有しているゲームから一度用意すれば、以降のバックポートすべてで再利用されます。",
