volumes_pkg_copies_hint: "この選択の意味：「アップロードしてインストール」は、まず .pkg ファイルを PS5 にコピーし、そのコピーからインストールします。ここで決めるのは、そのコピーを置くドライブだけです。ゲームのインストール先は変わりません（PS5 本体のストレージ設定で決まります）。「ストリームしてインストール」はコピーを一切残しません。選んだドライブが接続されていない場合、コピーは本体ストレージに保存されます。",
