"arcpkg.choose": "アーカイブを選択…",
"arcpkg.help": "任意のフォルダーに .pkg ファイルを 1 つ以上含む .zip、.7z、.rar が対象です。パッケージだけを PS5 に直接展開し（このコンピューターには何も展開しません）、ゲーム本体、アップデート、DLC の順に 1 つずつインストールします。分割 RAR（.part1.rar、.part2.rar…）にも対応しています。最初のパートを選び、残りは同じ場所に置いてください。RAR でパスワードが必要なときは入力を求めます。パスワード付きの ZIP と 7z には対応していません。",
"arcpkg.helpNoRar": "任意のフォルダーに 1 つ以上の .pkg を含む .zip または .7z 用です。パッケージだけを PS5 に直接展開し (このデバイスでは何も展開しません)、1 つずつインストールします: アップデートの前にベースゲーム、その後 DLC。パスワード付きファイルには対応しておらず、.rar にはデスクトップアプリが必要です。",
