"install.library.title": "PS5 上のパッケージのコピー",
"install.stream.file.help": ".pkg または .fpkg を選ぶか、このウィンドウのどこかにドロップしてください。インストールが終わるまでアプリを開いたままにしてください。進行状況は上のキューと「タスク」に表示されます。",
"install.stream.file.title": "パッケージファイルをインストール",
"install.tab.stream.lead": "PS5 がこのコンピューターまたはリンクから直接インストールします。先に PS5 へコピーを置かないため、PS5 側の空き容量は不要で、最も確実なインストール方法です。",
"install.tab.upload.lead": "まずパッケージを PS5 にコピーし、そのコピーからインストールします。PS5 からこのコンピューターに接続できない場合（ストリームがネットワークエラーで失敗する場合）や、パッケージを PS5 に残しておき、後でこのコンピューターなしで再インストールしたい場合に使います。",
"install.upload.file.browser": "ここからパッケージを PS5 にコピーするにはデスクトップアプリが必要です。Web UI では「ストリーム＆インストール」を使うか、下ですでに PS5 にあるパッケージをインストールしてください。",
"install.upload.file.help": ".pkg または .fpkg を選択します。コピーにはパッケージ全体分の PS5 の空き容量が必要で、削除するまで下のリストに残ります。",
"install.upload.file.title": "パッケージを PS5 にコピーしてインストール",
"linkcard.confirm.direct": "PS5 が自分でリンクからパッケージをダウンロードしてインストールします。開始後はこのコンピューターは不要で、進行状況はここではなく PS5（ダウンロード）に表示されます。PS5 がリンクに到達できない場合、アプリは代わりにこのコンピューター経由で中継します。インストール済みのゲームへの再インストールは、ソニーのインストーラーが失敗するとそのゲームを削除することがあります。信頼でき、インストールする権利のあるパッケージのリンクだけを使ってください。",
"linkcard.confirm.download": "このコンピューターがまずパッケージ全体をディスクに保存し、その後 PS5 にインストールします。両方の手順が終わるまで電源を入れたままにする必要があり、パッケージ分の空き容量が必要です。インストール済みのゲームへの再インストールは、ソニーのインストーラーが失敗するとそのゲームを削除することがあります。信頼でき、インストールする権利のあるパッケージのリンクだけを使ってください。",
"linkcard.confirm.stream": "このコンピューターがパッケージをダウンロードしながらそのまま PS5 に渡すため、インストールが終わるまで電源を入れ、接続したままにする必要があります。ディスクには何も保存されません。インストール済みのゲームへの再インストールは、ソニーのインストーラーが失敗するとそのゲームを削除することがあります。信頼でき、インストールする権利のあるパッケージのリンクだけを使ってください。",
"linkcard.confirm.title": "このリンクからインストールしますか？",
"linkcard.fact.awake": "このコンピューターをスリープさせないでください",
