stop: "停止",
activity_description_v2: "アプリが本体に対して実行中、または実行したすべての処理: アップロード、ダウンロード、インストール、ファイル操作。ここからどれでも停止または再試行できます。最新の 100 件が再起動後も保持されます。",
health_subtitle_v2: "PS5、このアプリ、その間のネットワークが正常に動作しているかを確認し、問題があれば直すべき点を示し、両者間のファイル転送速度を測定します。",
remotePlay_subtitle_v2: "この PS5 でリモートプレイを設定し、PS Remote Play アプリを本体にリンクするための PIN を取得します。",
saves_description_v2: "PS5 上のセーブデータ。ゲームごとに 1 件です。ゲームのセーブをこのコンピューターに .zip でバックアップし、後で復元できます。",
shell_description_v2: "PS5 のヘルパープロセス内で実行されるコマンドを入力します。上級者向けです。出力はコマンドごとに 256 KB までで、上下キーで以前のコマンドを呼び出せます。",
