connection_payload_engine_unreachable: "アプリがこのコンピューター上の自分のエンジンに接続できなかったため、ヘルパーが PS5 で起動したかどうかわかりません。PS5 の問題ではありません。ウィンドウ上部のお知らせに理由が表示され、エンジンを再起動できます。その後もう一度「ヘルパーを送信」を押してください。（{error}）",
"engine_problem.missing.fix": "ウイルス対策ソフトの隔離から ps5upload-engine を復元する（または許可する）か、アプリを再インストールしてください。",
"engine_problem.missing.why": "アプリのフォルダーにエンジンのプログラムがありません。セキュリティソフトが隔離することがあります。",
"engine_problem.port.fix": "「エンジンを再起動」を押してください。だめな場合は、ファイアウォールやウイルス対策ソフトで ps5upload-engine を許可し、アプリを再起動してください。",
"engine_problem.port.why": "何かがエンジンのアドレス（{url}）を使っていますが応答しません。そのポートを使う別のプログラムか、接続を遮断しているセキュリティソフトです。",
"engine_problem.proxy.fix": "ローカルアドレス（127.0.0.1）に対してプロキシや VPN ツールをオフにするか、http_proxy / ALL_PROXY の設定なしでアプリを起動してください。",
"engine_problem.proxy.why": "エンジンへのリクエストが、エンジンではなくこのコンピューターに設定されたプロキシに送られました。",
"engine_problem.remote.fix": "エンジン（Docker コンテナーまたは別のコンピューター）が動作し、そのアドレスで接続できるか確認するか、「設定」でアドレスを変更してください。",
"engine_problem.remote.why": "このアプリが使うよう設定されたエンジン（{url}）が応答しません。",
"engine_problem.restart": "エンジンを再起動",
"engine_problem.slow.fix": "「エンジンを再起動」を押してください。ローカル接続をフィルターするファイアウォールやウイルス対策ソフトが原因のこともあります。ps5upload-engine を許可してください。",
"engine_problem.slow.why": "エンジンは動作していますが応答しません。",
"engine_problem.stopped.fix": "「エンジンを再起動」を押してください。また止まる場合は「ログ」画面に理由が表示されます。",
"engine_problem.stopped.why": "エンジンが動作していません。停止したか、起動しませんでした。",
"engine_problem.title": "アプリがこのコンピューター上のエンジンに接続できません",
"engine_problem.phone.title": "アプリがエンジンに接続できません",
