"engine_problem.phone.fix": "アプリを完全に閉じて、もう一度開いてください。",
"engine_problem.web.fix": "サーバー（Docker コンテナー）が動作しているか確認してから、このページを再読み込みしてください。",
"engine_problem.web.why": "このページは、配信元の ps5upload サーバーとの接続を失いました。",
gate_engine_down_body_v2: "この画面にはアプリのエンジンが必要ですが、応答がありません。ウィンドウ上部のお知らせに理由が表示され、再起動できます。",
"profile.np.body": "Sony に接続することなく、サインイン中のアカウントを PlayStation Network にサインイン済みとして PS5 に扱わせます。本体の一部の機能はサインイン済みのアカウントにしか開かれず、リモートプレイもその一つです。earthonion の np-fake-signin を使い、ボタンを押したときにプロジェクトページから取得します。",
"profile.np.confirm_title": "このアカウントをサインインさせますか？",
"profile.np.failed": "サインインは実行されませんでした",
"profile.np.fetching": "np-fake-signin を取得しています…",
