"profile.np.sent": "np-fake-signin {version} を PS5 で実行しました。PS5 を再起動すると完了です。アカウントがサインイン済みとして表示され、「設定 > システム > リモートプレイ」をオンにできます。",
"profile.np.sign_in": "サインイン",
"profile.np.state_loading": "アカウントを読み取っています…",
"profile.np.state_no_slot": "上のアカウントに {user} という名前のものがないため、np-fake-signin は中止されます。アカウントにサインイン中のユーザーと同じ名前を付けるか、そのユーザー用のアカウントを有効化してください。",
"profile.np.state_no_user": "PS5 にサインインしているユーザーがいません。使うプロフィールにサインインしてから戻ってください。",
"profile.np.state_not_activated": "{user}（アカウント {slot}）にはまだアカウント ID がありません。先に上の「アカウント」で有効化してください。",
"profile.np.state_ready": "準備完了：{user}（アカウント {slot}）は有効化されています。",
"profile.np.step_activate": "アカウントにはアカウント ID が必要です。PSN に連携済みのアカウントには ID があります。ない場合は上の「アカウント」で有効化してください（オフライン有効化）。",
"profile.np.step_run": "そのユーザーで PS5 にサインインした状態で「サインイン」を押します。一度実行されて終了します。",
