kernellog_categories_explainer: "すべてのカテゴリーは最初は表示されています。Sony のカテゴリーは本体自身のサブシステムで、どのペイロードが動作していても、脱獄したすべての PS5 で常にログを出力します。ps5upload が原因ではありません。チェックを外すとノイズを減らせます。",
