payloads_description_catalog_v2: "厳選されたサードパーティ製の PS5 自作ペイロード。最新リリースを確認し、一度ダウンロードすれば、ワンクリックで PS5 に送信できます。バージョンはローカルにキャッシュされるので、USB ペイロードスティックに入れることもできます。",
payloads_description_send_v2: "任意の PS5 ペイロードファイル — .elf、.bin、.js、.lua、.jar（kstuff、自作ローダー、ブラウザー段階のエクスプロイト、プラグインスクリプト、BD-JB JAR）— を PS5 に送信します。接続画面と同じ流れで、選んだファイルを対象にします。ポートはファイルの種類で決まります（.elf/.bin 9021、.jar 9025、.lua 9026、.js 50000）。ローダーが別のポートで待ち受けている場合のみ変更してください。",
