"connection_send_payload_moved": "別のペイロード（kstuff、etaHEN、任意の .elf）を送りますか？それは「ペイロード」→「ペイロード送信」にあります。この画面が送るのは PS5Upload ヘルパーだけです。",
"connection_send_payload_open": "「ペイロード送信」を開く",
"upload_elf_title": "これはペイロード（.elf）で、ゲームではありません",
"upload_elf_body": "アップロードしてもファイルがコピーされるだけです。ShadowMount+ が取り込むのはゲームフォルダー（eboot.bin と sce_sys を含むもの）とゲームイメージだけで、.elf は対象外なので、ホーム画面には表示されません。実行するには、代わりに本体のローダーへ送ってください。アップロードすべきなのは、.ffpkg や .exfat イメージ、または eboot.bin を含むフォルダーとして配布される homebrew アプリです。",
"netdoctor.hint.below_test": "このアップロードは {speed} で動いており、速度テストで測った {expected} を大きく下回っています。",
"netdoctor.hint.runs_at": "このアップロードは {speed} で動いています。",
"netdoctor.hint.cause_source": "遅いのはネットワークではなく、このコンピューター上のファイルの読み取りです。USB ドライブやハードディスク、ネットワーク共有（NAS）、アーカイブの展開は回線より遅くなります。先にゲームを内蔵 SSD にコピーするか、アーカイブを展開してからそのファイルをアップロードすると全速が出ます。",
"netdoctor.hint.cause_disk": "遅いのはネットワークではなく PS5 のドライブです。外付け USB ドライブ、空きの少ないドライブ、何千もの小さなファイル（1 つごとに時間がかかります）は、回線が届ける速さより遅く書き込みます。ゲームイメージ（.ffpkg や .exfat）なら 1 つのファイルとして送られます。",
"netdoctor.hint.cause_workers": "PS5 は受け取ったデータをまだ書き込んでいる最中で、ネットワーク待ちではありません。小さなファイルが多いと 1 つごとに時間がかかります。ゲームイメージ（.ffpkg や .exfat）なら 1 つのファイルとして送られます。",
"netdoctor.hint.cause_cap": "遅いのはアップロード速度制限（約 {cap} MiB/s、この画面と設定で指定）のためです。0 にすると制限がなくなります。",
"profile.np.confirm_body_v2": "np-fake-signin は {user} の PlayStation Network サインイン用ファイルと設定を PS5 に書き込みます。Sony には何も送信されません。その後 PS5 を再起動してください。",
"profile.np.side_effect": "既知の副作用：その後、一部の本体ではゲームを開くたびに「PS5 本体の利用制限を一時的に解除」するよう求められ、設定 > ユーザーとアカウント > その他 > サインアウト がグレー表示のままになることがあります。アプリは np-fake-signin が PS5 で変更するものすべてのコピーを先に本体に残すので、ここの「サインインを元に戻す」で元どおりにできます。",
"profile.np.backing_up": "アカウントの現在の設定のコピーを PS5 に保存しています…",
"profile.np.backup_failed": "PS5 がアカウントの設定のコピーを保存できなかったため、np-fake-signin は実行されませんでした。ヘルパーをこのアプリのバージョンに置き換えて、もう一度お試しください。({error})",
"profile.np.step_restart_v2": "PS5 を再起動します。後で元に戻すには、ここで「サインインを元に戻す」を押してもう一度再起動します。",
"profile.np.undo": "サインインを元に戻す",
"profile.np.undo_hint": "サインイン前のこのアカウントの設定のコピーが PS5 に保存されています。これで元に戻します。",
"profile.np.undo_confirm_title": "サインインを元に戻しますか？",
"profile.np.undo_confirm_body": "{user} の設定とファイルを np-fake-signin の実行前の状態に戻します。その後 PS5 を再起動してください。サインイン済みのアカウントが必要な機能（リモートプレイなど）は、もう一度サインインするまで開けなくなる場合があります。",
"profile.np.undoing": "設定を元に戻しています…",
"profile.np.undone": "元に戻しました（設定とファイル {count} 件）。完了するには PS5 を再起動してください。",
"profile.np.no_backup": "このアカウントには np-fake-signin のテンプレート設定（生年月日 1983-04-12、オフライン成人フラグがオフ）が入っており、この PS5 には以前のコピーが残っていないため、アプリでは元に戻せません。ゲームを開く前に本体の利用制限を一時的に解除するよう求められる場合は、設定 > ファミリーとペアレンタルコントロール > PS5 本体の利用制限（変更していなければパスコードは 0000）で制限を解除してください。",
