"play_setup_needs_https": "このページは通常の http で開かれているため、Play はここで映像を表示できません。ブラウザーが映像をデコードするのは https か、エンジンを実行しているコンピューター上だけです。https で開く(REVERSE_PROXY.md を参照)か、デスクトップアプリを使用してください。",
"play_setup_description": "プレイは Remote Play で PS5 をこのアプリに配信します。これらの手順で本体を一度準備します。各手順は終わると自動でチェックされます。",
"play_setup_from_accounts": "プレイを設定中ですか？ プレイ › 設定 で各手順を順に進め、自動でチェックします。",
"play_setup_other_apps": "ソニーの PS Remote Play アプリや chiaki-ng を使いたい場合は、アカウント › Remote Play で必要な PIN を作れます。",
"play_setup_pair": "ペアリング",
"play_setup_pair_body": "ワンタップでこのアプリを PS5 に登録し（PS Remote Play アプリのペアリングと同じ）、鍵をこの端末に保存します。配信、起動、サインインはこれを使います。本体の初期化やユーザー変更後はもう一度ペアリングしてください。",
"play_setup_play_body": "プレイを開いてスタートを押すと、アプリがレストモードの本体を起こし、サインインして配信します。最初の映像でこの手順にチェックが付きます。",
