"play_setup_rest_undo": "まだです",
"play_setup_short": "設定",
"play_setup_signin_body": "PS5 はサインイン済みのアカウントにしか配信を許しません。ここでオフラインサインインを実行し（ソニーには何も送られません）、PS5 を再起動してヘルパーを送り直してください。本体が戻ると自動でチェックされます。",
