"conn_from_root": "サーバー全体を参照",
"conn_from_root_on": "フォルダーは SSH や FTP クライアントが表示するとおりのサーバー自身のパスです（/home/you、/mnt/games）。開始フォルダーと参照先は、このアカウントが読める場所ならどこでもかまいません。開始フォルダーがなければ、サーバーにログインした場所で開きます。",
