"fs_hide_hint": "先頭にドットを付けて名前を変更します。ShadowMount+ のスキャンはこれを飛ばすため、ゲームの別のコピーが使われます。",
"fpkg.ps4_game_note_v2": "PS4 ゲームです。PS4 パッケージ、ゲームイメージ、またはフォルダーに変換できます。イメージやフォルダーには ShadowMount+ に必要な param.json が追加されます。",
"fpkg.ps4_merged_note_v2": "アップデートを統合した PS4 ゲーム {title}：{from} が {to} になります。そのバージョンの PS4 パッケージ、ゲームイメージ、またはフォルダーに変換されます。",
"fpkg.ps4_patch_note_v2": "{title} 用の PS4 アップデート（バージョン {version}）です。変更されたファイルだけを含むため、単体ではゲームではありません。下で統合先のゲームを選ぶと、作成するものはこのバージョンのゲームになります。",
"fpkg.ps4_pkg.options": "PS4 パッケージはゲームのファイルをそのまま保持します。圧縮はされず、ゲームのすべての言語が残り、パッケージを保存する前にすべてのファイルが読み戻されて比較されます。",
"fpkg.ps4_licence_note": "{title} 用のこの PS4 追加コンテンツはライセンスのみです。ゲーム内の要素を解除するだけでファイルを含まないため、変換するものはありません。",
"fpkg.ps4_addon_note": "{title} 用の PS4 追加コンテンツです。ファイルはイメージやパッケージではなくフォルダーになります。ShadowMount+ は追加コンテンツをマウントしないため、ゲーム自身が探す場所（ゲーム内のフォルダーなど）に置いた場合にのみゲームに届きます。",
