"fpkg.image.zstd": "zstd アセットパック（最小、ShadowMount+ 用）",
"fpkg.image.zstd_body": "ゲームのシステムファイル以外をすべて zstd パックにまとめ、一時コピーなしでイメージへ直接書き込みます。イメージには quer3q の ampr-emu-ng がエミュレーターとして入り、使う前に公開されたダイジェストで確認します。LZ4 パック済みのゲームは切り替えられます。ShadowMount+ の update_emulators をオフにしてください。オンのままだと、これらを読めないエミュレーターに置き換えられることがあります。",
"fpkg.image.zstd_level": "圧縮レベル",
"fpkg.image.zstd_runtime": "パックのランタイム",
"fpkg.image.zstd_runtime_latest": "最新リリース（既定）",
"fpkg.image.zstd_runtime_pinned": "検証済み {version}",
"fpkg.image.zstd_runtime_body": "「最新」は GitHub 上の ampr-emu-ng の最新リリースを、GitHub が公開する SHA-256 と一致したときだけ使います。一致しない場合やオフラインのときは検証済みの {version} が入ります。「検証済み」は常に {version} を使います。",
"fpkg.folder.zstd_body": "ゲームを通常のフォルダーとして書き出します。システムファイル以外はすべて zstd パックに入り、quer3q の ampr-emu-ng が fakelib/libSceAmpr.sprx として入ります。ゲームフォルダーも元にできます。LZ4 パックはここでは選べません（.exfat イメージ専用です）。ShadowMount+ の update_emulators をオフにしてください。オンのままだと、これらを読めないエミュレーターに置き換えられることがあります。",
"ampr_emu_add_hint": "このゲームは AMPR 経由でファイルを読み込み、エミュレーターがありません。こうしたゲームには、なしではイメージから起動しないものも、問題なく動くものもあります。drakmor の ampr_emu 0.4.2.1 を追加します。一度だけ取得し、既知のダイジェストで確認します。イメージは変更されません。エミュレーターは ShadowMount+ の backport フォルダーに入ります。",
"ampr_emu_done_backport": "ShadowMount+ の backport として {folder} に追加しました。イメージは変更されていません。ゲームを起動して試してください。",
"ampr_emu_done_folder": "ゲームのフォルダー {folder} に追加しました。ゲームを起動して試してください。",
"fpkg.fake_sign_note": "このゲームの署名なし実行ファイル {count} 個は、変換時に偽署名されます。そうしないと起動しません。元のファイルは変更されません。",
"fpkg.image.ampr_emu": "AMPR エミュレーターを追加",
"fpkg.image.ampr_emu_body": "このゲームは AMPR 経由でファイルを読み込み、エミュレーターがありません。こうしたゲームには、なしではイメージから起動しないものも、問題なく動くものもあります。drakmor の ampr_emu 0.4.2.1 を fakelib/libSceAmpr.sprx として追加します。GitHub のリリースから一度だけ取得し、既知のダイジェストで確認します。",
"fpkg.image.lz4_placement_note": "パック済みイメージは本体の内蔵ストレージに置いてください。USB から起動すると黒い画面で止まった報告があります。ShadowMount+ の update_emulators をオフにしてください。オンのままだと、パックを読めないエミュレーターに置き換えられることがあります。",
