"rp_err_rp_off": "PS5 のリモートプレイがオフになっています。本体で 設定 › システム › リモートプレイ を開き、「リモートプレイを有効にする」をオンにしてください（すでにオンなら一度オフにしてからオンに戻す）。その後 開始 を押してください。グレー表示の場合: PS5 ユーザーのアカウントが有効化されている必要があります。また、sp-int NP 環境に切り替えた PS5 ではオフのままになります。np に戻してください。",
"rp_err_refused": "PS5 がリモートプレイの開始を拒否しました。本体で 設定 › システム › リモートプレイ › 「リモートプレイを有効にする」を確認し（オフにしてからオンに）、Play › セットアップ で「許可」を押すか、ペアリングし直してください。下のコードがどの拒否かを示します。それでも拒否される場合は PS5 を再起動してください。長時間つけっぱなしの本体は再起動するまで拒否することがあります。",
"web_update_how_docker": "更新するには、compose ファイルのあるフォルダーでこれを実行してください（Watchtower に任せることもできます）：",
