"dump_decrypt_risk": "復号するとコンソールがフリーズすることがあります",
"dump_decrypt_risk_body": "復号のため、ヘルパーは実行ファイルごとに、すべてのプログラムが使うシステムの一部を一時的に差し替えます。その瞬間にゲームがファイルを読むと、コンソールがフリーズして強制的に電源を切る必要が出ることがあります。処理中はゲームのスタート画面のままにしてください。ファームウェア 13.60 までのみ対応。それ以降ではダンプは単純コピーになります。",
