"rp_picture_here": "このデバイスの映像",
"rp_picture_here_hint": "オフにすると、新しいストリームはここでは映像・音声・コントローラーなしで始まり、このデバイスの CPU とバッテリーを節約します。Play Together の友達と Go live にはストリームが届き続け、ストリームからいつでもオンにできます。",
"rp_picture_off_title": "このデバイスの映像はオフです",
"rp_picture_off_body": "友達と配信にはストリームが続きます。ここでは音声もコントローラーもないので、このデバイスの処理はほとんどありません。",
"rp_picture_turn_on": "映像をオンにする",
"rp_picture_turn_off": "このデバイスの映像をオフにする",
"golive_picture_hint": "オフにすると、このコンピューターはデコードも表示もせずにストリームを送り出し、CPU と発熱を抑えます。アプリは起動したままにしてください。操作はここで続けられます。",
"pt_picture_hint": "オフにすると、このデバイスは友達を招待するだけになります。ここでは映像・音声・コントローラーはなく、友達のゲームは続きます。テレビでプレイするときに。",
"pt_tv_title": "テレビでプレイしますか？",
"pt_tv_note": "このストリームは、PS5Upload とペアリングした PS5 ユーザーでサインインしています。本体の DualSense で PS を押して別のユーザーを選ぶと、それがテレビでのあなたになります。ストリームと同じユーザーを選ぶと、友達も含めて全員のストリームが終わります。ストリームのユーザーもプレイヤーとして数えるゲームがあり、友達の枠が 1 つ減ることがあります。",
"pt_tv_seats": "PS5 に接続できるコントローラーは 4 台です。テレビで DualSense を使う場合、最初のフレンドはストリーム自体のコントローラーを使い、そのユーザーとしてプレイします（ユーザー選択は不要）。さらに 2 人は専用のコントローラーを使えるので、フレンドは 3 人まで参加できます。",
"pt_stream_seat_note": "フレンドがこのストリームのコントローラーを使っているため、退出するまでここのコントローラーではプレイできません。",
"queue_waiting_for_engine_queue": "待機中: スクリプトまたはエージェントがエンジンのキューでこの PS5 を使用しています。終わると自動で続行します。",
