"settings_ps5_picker_hint": "これらの設定はこの PS5 専用です。本体ごとに別々の設定があり、ほかのデバイスにも引き継がれます。",
"auto_bringup_hint_ps5": "この PS5 のローダー（elfldr、ポート 9021）が動いていてヘルパーが動いていないとき、アプリが自動でクイック起動を実行します：設定していればこの PS5 の起動プレイリスト、次にヘルパー、次にオートローダーのプレイリスト。この PS5 が起動するたびに 1 回実行し、レストモードからの復帰後はヘルパーだけを送り直します。本体のオートローダーが先に終わるよう、ローダーが現れてから約 90 秒待ちます。初期設定はオフです。",
"bringup_playlist_label_ps5": "この PS5 の起動プレイリスト（kernel R/W, SMP）",
"bringup_playlist_hint_ps5": "クイック起動のとき、ヘルパーより先に実行されます。ペイロードはファームウェアによって異なるため、PS5 ごとに別々に設定します。プレイリストはペイロードで作成します。",
"upload_auto_redeploy_on_wake_hint_ps5": "この PS5 のヘルパーがオフラインになったとき（レストモード、Wi-Fi の切り替え、ペイロードのクラッシュ）、バックグラウンドで送り直しを続けます。再び接続できるようになると、ヘルパー、この PS5 のファンしきい値、アップロード用ポートが自動で戻ります。初期設定はオンです。",
"keep_ps5_awake_mode_hint_ps5": "この PS5 の自動スタンバイのタイマーをリセットして、レストモードに入らないようにします。「アップロードとインストール中」は長いアップロードを守ります（アップロード失敗のよくある原因です。初期設定）。「接続中は常に」は、ヘルパーが動いていてアプリが開いている間、この PS5 をレストモードにしません。自分で PS5 をレストモードにすることは、どのモードでもできます。",
"upload_rest_after_hint_ps5": "この PS5 のアップロードキューが終わったら、レストモードに入るよう指示します。夜通しのキューに便利です。少なくとも 1 件のアップロードが完了したときだけです（停止したときや全部失敗したときは除く）。初期設定はオフです。レストモードを拒否するファームウェアもあり、この PS5 が拒否した場合はお知らせが表示されます。",
"upload_wake_for_uploads_hint_ps5": "レストモード中のこの PS5 向けにアップロードが待っているとき、起動信号を送り、ヘルパーが戻ったら続行します。接続画面でこの PS5 の起動設定が必要です。初期設定はオンです。",
"install_path_fallback_hint_ps5": "すでにこの PS5 にあるパッケージのための最後の手段です。PS5 が自身のストレージからのパッケージを拒否し、このコンピューターからも取得できない場合に使います。インストールされていない本編ゲームにだけ使うので、何かを削除することはありません。実績は不十分です：ファームウェア 11.20 では成功し、13.60 では拒否されたため、PS5 ごとに設定します。試した場合は、うまくいったかどうかをお知らせください。",
